INSERT INTO feature VALUES('higher-order-fields','descriptions','Function fields in described families','levitated-descriptions','partial','notable',NULL,'A constructor field written `A => T` is the description code''s function former over its domains, decoded to the thunked arrow the native reading gives it, so a presented type holds a continuation: programs over a state, quotiented by put-put, check, and their state-passing handler folds through a read''s continuation while a store count is refused by the rule. An observation taking an argument has no code yet (#2859), and a rule applying a continuation is refused (#2861).','theory-levitation core-term surface-lowering','corpus/model/desc/function-field.gandr corpus/pathological/desc/function-field.gandr corpus/ledger/features/higher-order-fields.gandr','corpus/ledger/features/higher-order-fields.gandr','#2859');
